/// One embedded story image (the opt-in "Show images in stories" setting).
/// Loads via AsyncImage — images live on the author's external image host,
/// not AO3, so they don't go through the AO3 throttle; the shared URLCache
/// gives basic reuse. Never persisted, so downloaded works stay text-only.
struct ReaderInlineImage: View {
    let url: URL
    /// The page-by-page mode measures every block's height up front, so an
    /// image there must occupy a fixed, known height. nil (continuous /
    /// swipe-by-chapter) lets the image size to fit naturally.
    var fixedHeight: CGFloat? = nil

    /// The height an image slot occupies in page-by-page pagination math —
    /// must match what `ReaderPageCell` renders or pages overflow.
    static let paginatedHeight: CGFloat = 240

    var body: some View {
        AsyncImage(url: url) { phase in
            switch phase {
            case .success(let image):
                image
                    .resizable()
                    .aspectRatio(contentMode: .fit)
                    .clipShape(RoundedRectangle(cornerRadius: 8))
            case .failure:
                Label("Image unavailable", systemImage: "photo")
                    .font(.caption)
                    .foregroundStyle(.secondary)
            case .empty:
                ProgressView()
            @unknown default:
                EmptyView()
            }
        }
        .frame(maxWidth: .infinity)
        .frame(maxHeight: fixedHeight ?? 480)
        .frame(height: fixedHeight)
        .accessibilityLabel("Story image")
    }
}

