export const meta = {
  name: 'audit-and-bughunt',
  description: 'Review the image-toggle diff + PR21 fix, hunt real bugs across the repo, adversarially verify',
  phases: [
    { title: 'Diff review', detail: '3 lenses over the working-tree image-toggle diff' },
    { title: 'Bug hunt', detail: '4 subsystem finders across the repo' },
    { title: 'Verify', detail: '3-voter adversarial verification per finding' },
  ],
}

const REPO = '/Users/jenny/Work/ao3-app'
const DIFF = '/private/tmp/claude-501/-Users-jenny-Work-ao3-app/936f110b-7dd0-4618-ae44-7b95062ac703/scratchpad/imagetoggle.diff'
const PR21 = '/private/tmp/claude-501/-Users-jenny-Work-ao3-app/936f110b-7dd0-4618-ae44-7b95062ac703/scratchpad/pr21fix.diff'

const BASE = `Fanficly: a SwiftUI iOS/Catalyst app (Swift 6, iOS 17+) that reads AO3 fanfiction by scraping HTML with SwiftSoup through one throttled URLSession. Privacy posture: nothing leaves the device except the user's own iCloud. Repo: ${REPO}. Read ${REPO}/CLAUDE.md first for architecture. IGNORE the untracked android/, .entire/, .claude/, and build/ directories entirely. Do NOT modify any files — report only. Report REAL defects (crashes, logic errors, races, data loss, wrong behavior a user would hit), not style opinions. For each finding give a concrete failure scenario.`

const FINDINGS_SCHEMA = {
  type: 'object',
  required: ['findings', 'assessment'],
  properties: {
    assessment: { type: 'string' },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        required: ['title', 'severity', 'detail', 'file', 'suggestedFix'],
        properties: {
          title: { type: 'string' },
          severity: { type: 'string', enum: ['blocker', 'major', 'minor', 'nit'] },
          detail: { type: 'string', description: 'concrete failure scenario, with file:line refs' },
          file: { type: 'string' },
          suggestedFix: { type: 'string', description: 'the smallest safe fix' },
        },
      },
    },
  },
}

const VERDICT_SCHEMA = {
  type: 'object',
  required: ['isReal', 'reasoning'],
  properties: {
    isReal: { type: 'boolean', description: 'true only if you could NOT refute it from the actual code' },
    reasoning: { type: 'string' },
  },
}

const DIFF_LENSES = [
  { key: 'alignment', prompt: `${BASE}

Review the uncommitted working-tree diff at ${DIFF} (a new opt-in setting "reader.showImages" that renders <img> tags embedded in AO3 chapters; default off must be byte-for-byte the old behavior). LENS: paragraph-index integrity. The reader's reading-position anchors (c<chapter>-p<index>), TTS karaoke highlighting (speechParagraphs index-aligned with convertParagraphs), progress fraction, and page-by-page pagination all share paragraph indices. Verify: every call site converts with the SAME includeImages flag; the NSCache keys can't collide; toggling the setting mid-session (reader open, TTS playing, pages built) can't crash or badly misalign; saved ReadingProgress written with images-on restored images-off only drifts, never crashes; speech skips image slots. Also sanity-check the small committed test fix at ${PR21}. Read the full post-change files in ${REPO} (HTMLToAttributed.swift, ChapterContentView.swift, ReaderView.swift), not just the diff.` },
  { key: 'rendering', prompt: `${BASE}

Review the uncommitted working-tree diff at ${DIFF} (opt-in inline story images). LENS: SwiftUI rendering, pagination math, performance. Verify: ReaderPageCell fixed-height budget (ReaderInlineImage.paginatedHeight) matches what calculateHeight returns INCLUDING how paragraphSpacing is added around blocks in paginateChapter's loop; AsyncImage phase handling (loading/failure states, cell reuse inside TabView, repeated re-fetch on page turns); the ContentKey task id (does .task(id:) re-fire correctly when the setting flips while the view is on screen); the Group/id/anchorReporter restructure in ChapterContentView preserves scroll-anchor reporting semantics (stride, preference keys); frame(maxWidth/maxHeight/height) combination on ReaderInlineImage behaves for tall/wide/failed images; NSCache growth with the new keys. Read the full files in ${REPO}.` },
  { key: 'privacy-ux', prompt: `${BASE}

Review the uncommitted working-tree diff at ${DIFF} (opt-in inline story images). LENS: privacy posture, AO3 etiquette, URL safety, settings UX. Verify: resolvedImageURL rejects data:/javascript:/file: and weird schemes robustly (try adversarial srcs: "javascript:alert(1)", "HTTP://x", "https://", "//"), http→https upgrade is correct string surgery, root-relative resolution against archiveofourown.org is right for AO3 markup; AsyncImage bypassing the AO3 throttle is OK for third-party hosts but check: can an <img> point AT archiveofourown.org and thus make unthrottled AO3 requests, and does that matter at reader scale? Settings copy accuracy (images NOT stored offline — verify nothing persists them; is the wording honest about IP exposure); default-off really is unchanged behavior everywhere including demo mode/screenshots and widget. Read the full files in ${REPO}.` },
]

const HUNT_AREAS = [
  { key: 'networking-parsers', prompt: `${BASE}

BUG HUNT over Fanficly/Networking/ (AO3Client.swift, AO3Endpoints.swift, ThrottleActor.swift, HTMLParsers/*) and Fanficly/Search/ (TagResolver, SearchPromptParser, AO3SearchFilters). Look for: parsing edge cases that crash or silently drop data (force-unwraps, index math, regex), URL-building bugs (encoding, pagination), error-mapping mistakes, cookie/auth handling races, cache-correctness issues. Return the top real defects with concrete failing inputs.` },
  { key: 'reader', prompt: `${BASE}

BUG HUNT over Fanficly/Reader/ (ReaderView.swift is ~2000 lines — pagination math, reading-position save/restore, reading-time spans; SpeechController.swift concurrency; ReadingProgressStore.swift; ReaderProfile.swift; HTMLText.swift; WorkExportButton.swift). Look for: off-by-one in chapter/paragraph/page math, races between restore and user scroll, TTS state machine bugs (chapter advance, backgrounding, deallocation), reading-time accounting bugs (span caps, double counting), profile migration/merge bugs. Return the top real defects with concrete scenarios.` },
  { key: 'persistence-sync', prompt: `${BASE}

BUG HUNT over Fanficly/Models/Work.swift, Fanficly/Library/ (WorkPersistence.swift, iCloudSyncManager.swift, LibraryView.swift), stats code (ReadingStatsStore/Aggregator/Backfill in ReadingProgressStore.swift + LibraryView.swift), and WidgetProgressStore.swift. Look for: SwiftData upsert races/duplicates, backup/restore merge bugs that lose or double-count data, date/calendar bugs in stats bucketing (timezones, DST, week boundaries), widget sync staleness/conflict bugs. Return the top real defects with concrete scenarios.` },
  { key: 'subs-integration', prompt: `${BASE}

BUG HUNT over Fanficly/Subscriptions/ (poller + views), Fanficly/Auth/, RootView.swift (deep links, resume route, zoom), FanficlyApp.swift (BG task, container, launch tasks), FanficlyShare/, FanficlyWidget/. Look for: notification logic that misses or duplicates alerts (knownWorkIds seeding, poll ordering), deep-link parsing bugs, background-task scheduling mistakes, Keychain/cookie persistence bugs, app-group/KVS sync bugs, main-actor violations. Return the top real defects with concrete scenarios.` },
]

const review = pipeline(
  DIFF_LENSES,
  l => agent(l.prompt, { label: `diff:${l.key}`, phase: 'Diff review', schema: FINDINGS_SCHEMA, effort: 'high' })
)
const hunt = pipeline(
  HUNT_AREAS,
  h => agent(h.prompt, { label: `hunt:${h.key}`, phase: 'Bug hunt', schema: FINDINGS_SCHEMA, effort: 'high' })
)
const [reviewResults, huntResults] = await Promise.all([review, hunt])

const all = []
for (const [i, r] of [...reviewResults, ...huntResults].entries()) {
  if (!r) continue
  const source = i < DIFF_LENSES.length ? `diff:${DIFF_LENSES[i].key}` : `hunt:${HUNT_AREAS[i - DIFF_LENSES.length].key}`
  for (const f of r.findings) all.push({ ...f, source })
}
log(`${all.length} raw findings collected`)

// Dedup by file+title similarity is overkill; verify blocker/major, keep minor as advisory.
const serious = all.filter(f => f.severity === 'blocker' || f.severity === 'major')
const advisory = all.filter(f => f.severity !== 'blocker' && f.severity !== 'major')
log(`${serious.length} serious findings to verify, ${advisory.length} advisory`)

phase('Verify')
const verified = await parallel(serious.map(f => () =>
  parallel(['correctness', 'reproduce-it', 'is-it-preexisting-or-hypothetical'].map(lensName => () =>
    agent(`${BASE}

A reviewer (${f.source}) claims this defect. Your lens: ${lensName}. Adversarially try to REFUTE it by reading the actual code in ${REPO} (for diff findings, the working tree already contains the change; diffs at ${DIFF} and ${PR21}). isReal=true only if the defect is concretely reproducible as described AND would actually matter to a user or the codebase's stated invariants. Default to isReal=false if uncertain.

Title: ${f.title} [${f.severity}]
File: ${f.file}
Detail: ${f.detail}
Suggested fix: ${f.suggestedFix}`, { label: `verify:${f.title.slice(0, 36)}`, phase: 'Verify', schema: VERDICT_SCHEMA })
